func (this *Test_org_eclipse_swt_graphics_GC) Test_drawImageLorg_eclipse_swt_graphics_ImageIIII_ImageDataProvider() {
	var width int32 = 32
	var height int32 = 48
	var drawToImage *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(this.display), width, height)
	var gc *swt.GC = swt.NewGCDrawable(upcastswtImageToswtDrawable(drawToImage))
	gc.SetAntialias(swt.OFF)
	var drawnRgb *swt.RGB = swt.NewRGB(255, 255, 255)
	var undrawnRgb *swt.RGB = swt.NewRGB(0, 0, 0)
	var imageDataProvider swt.ImageDataProvider = &ImageDataProviderFunc{fn: func(zoom int32) *swt.ImageData {
		if zoom != 100 {
			return nil
		}
		var palette *swt.PaletteData = swt.NewPaletteDataRedMaskGreenMaskBlueMask(0xFF0000, 0xFF00, 0xFF)
		var imageData *swt.ImageData = swt.NewImageData(16, 16, 32, palette)
		var drawnPixel int32 = palette.GetPixel(drawnRgb)
		for i := int32(0); i < 16; i++ {
			imageData.SetPixel(i, 0, drawnPixel)
			imageData.SetPixel(i, 15, drawnPixel)
			imageData.SetPixel(0, i, drawnPixel)
			imageData.SetPixel(15, i, drawnPixel)
		}
		return imageData
	}}
	var image *swt.Image = swt.NewImageDeviceImageDataProvider(upcastswtDisplayToswtDevice(this.display), imageDataProvider)
	{
		defer func() {
			image.Dispose()
			drawToImage.Dispose()
		}()
		gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, width, height)
		var zoom int32 = swt.DPIUtilGetDeviceZoom()
		var printedImageData *swt.ImageData = drawToImage.GetImageDataZoom(zoom)
		var printedPalette *swt.PaletteData = printedImageData.Palette
		junit.AssertEquals(drawnRgb, printedPalette.GetRGB(printedImageData.GetPixel(0, 0)))
		junit.AssertNotEquals(undrawnRgb, printedPalette.GetRGB(printedImageData.GetPixel(1, 1)))
		junit.AssertNotEquals(undrawnRgb, printedPalette.GetRGB(printedImageData.GetPixel(1, 2)))
		junit.AssertEquals(undrawnRgb, printedPalette.GetRGB(printedImageData.GetPixel(swt.DPIUtilPointToPixel(width, zoom)/2, swt.DPIUtilPointToPixel(height, zoom)/2)))
		junit.AssertNotEquals(undrawnRgb, printedPalette.GetRGB(printedImageData.GetPixel(swt.DPIUtilPointToPixel(width, zoom)-2, swt.DPIUtilPointToPixel(height, zoom)-3)))
		junit.AssertNotEquals(undrawnRgb, printedPalette.GetRGB(printedImageData.GetPixel(swt.DPIUtilPointToPixel(width, zoom)-2, swt.DPIUtilPointToPixel(height, zoom)-2)))
		junit.AssertEquals(drawnRgb, printedPalette.GetRGB(printedImageData.GetPixel(swt.DPIUtilPointToPixel(width, zoom)-1, swt.DPIUtilPointToPixel(height, zoom)-1)))
	}
}

