func (this *Test_org_eclipse_swt_graphics_GC) Test_drawImage_nonAutoScalableGC_bug_2504() {
	var shell *swt.Shell = swt.NewShellDisplay(this.display)
	var targetScale float32 = 2.0
	var srcSize int32 = 50
	var image *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(this.display), srcSize, srcSize)
	var gcSrc *swt.GC = swt.NewGCDrawable(upcastswtImageToswtDrawable(image))
	gcSrc.SetBackground(this.display.GetSystemColor(swt.COLOR_BLACK))
	gcSrc.FillRectangle(0, 0, srcSize, srcSize)
	gcSrc.SetBackground(this.display.GetSystemColor(swt.COLOR_WHITE))
	gcSrc.FillRectangle(2, 2, srcSize-4, srcSize-4)
	gcSrc.Dispose()
	var bounds *swt.Rectangle = image.GetBounds()
	anon16 := &Test_org_eclipse_swt_graphics_GCAnon1{}
	anon16.Canvas = swt.NewCanvasParentStyle(upcastswtShellToswtComposite(shell), swt.NONE)
	anon16.SetImpl_(anon16)
	anon16.fnIsAutoScalable = func() bool {
		return false
	}
	var canvas *swt.Canvas = anon16.Canvas
	var canvasWidth int32 = int32(math.Floor(float64(float32(bounds.Width)*targetScale) + 0.5))
	var canvasHeight int32 = int32(math.Floor(float64(float32(bounds.Height)*targetScale) + 0.5))
	canvas.SetSize(canvasWidth, canvasHeight)
	var paintListenerCalled *jrt.AtomicBoolean = jrt.NewAtomicBoolean()
	canvas.AddPaintListener(&PaintListenerFunc{fn: func(e *swt.PaintEvent) {
		e.Gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, canvasWidth, canvasHeight)
		paintListenerCalled.Set(true)
	}})
	shell.Open()
	var timeoutMillis int32 = 2000
	SwtTestUtilProcessEventsTimeoutMsBreakCondition(timeoutMillis, func() bool {
		return paintListenerCalled.Get()
	})
	junit.AssertTrue(paintListenerCalled.Get(), "paint listener was never called")
	var target *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(this.display), canvasWidth, canvasHeight)
	var gcCopy *swt.GC = swt.NewGCDrawable(upcastswtCanvasToswtDrawable(canvas))
	gcCopy.CopyArea(target, 0, 0)
	gcCopy.Dispose()
	var data *swt.ImageData = target.GetImageData()
	var bottomRightX int32 = canvasWidth - 1
	var bottomRightY int32 = canvasHeight - 1
	var bottomRight *swt.RGB = data.Palette.GetRGB(data.GetPixel(bottomRightX, bottomRightY))
	var black *swt.RGB = swt.NewRGB(0, 0, 0)
	junit.AssertEquals(black, bottomRight, "Bottom-right pixel is not black! when source GC is not autoScalable")
	shell.Dispose()
	target.Dispose()
	image.Dispose()
}

